script:
ci = repo.search("(?i)fixme", glob = "src/**")
out = {"case_insensitive_count": len(ci), "results": ci}
# also scan every file under src recursively, including any unusual extensions
def walk(path, acc):
    for e in repo.list(path):
        if e.endswith("/"):
            walk(path + e, acc)
        else:
            acc.append(path + e)
files = []
walk("src/", files)
out["all_files"] = files
for f in files:
    c = repo.read(f)
    for i, line in enumerate(c.split("\n"), 1):
        if "fixme" in line.lower():
            out.setdefault("manual_hits", []).append({"file": f, "line": i, "text": line})
return out
